import{_ as t,o as r,c as a,a5 as i}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"质数判断","description":"判断一个数是否是质数，我们可以遵循一个基本的数学原则：一个质数是只能被1和它本身整除的大于1的自然数。这意味着，如果你在2到这个数的平方根之间找到任何一个数能整除它，那么它就不是一个质数。 以下是判断一个数是否为质数的步骤： 1. 检查是否小于2 ：如果数小于2，它不是质数。 2。","frontmatter":{"title":"质数判断","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"判断一个数是否是质数，我们可以遵循一个基本的数学原则：一个质数是只能被1和它本身整除的大于1的自然数。这意味着，如果你在2到这个数的平方根之间找到任何一个数能整除它，那么它就不是一个质数。 以下是判断一个数是否为质数的步骤： 1. 检查是否小于2 ：如果数小于2，它不是质数。 2。","sidebarWeight":12,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/JD3 质数因子/质数判断.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/JD3 质数因子/质数判断.md","filePath":"posts/前端面试与实战/03-算法训练/JD3 质数因子/质数判断.md"}'),n={name:"posts/前端面试与实战/03-算法训练/JD3 质数因子/质数判断.md"};function o(s,e,l,p,d,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<div><h1 id="质数判断" tabindex="-1">质数判断 <a class="header-anchor" href="#质数判断" aria-label="Permalink to &quot;质数判断&quot;">​</a></h1><blockquote><p>本节目标：理解“质数判断”的核心思路，并能把它用于实际开发或面试表达。 判断一个数是否是质数，我们可以遵循一个基本的数学原则：一个质数是只能被1和它本身整除的大于1的自然数。这意味着，如果你在2到这个数的平方根之间找到任何一个数能整除它，那么它就不是一个质数。</p></blockquote><p>以下是判断一个数是否为质数的步骤：</p><ol><li><strong>检查是否小于2</strong>：如果数小于2，它不是质数。</li><li><strong>检查2到该数的平方根之间的数</strong>：只需检查到它的平方根是因为，如果一个数不是质数，它必定有一个因子小于等于它的平方根。</li><li><strong>检查是否有因子</strong>：如果这个数能被任何一个数整除，那么它不是质数。</li></ol><p>下面是一个简单的Python代码示例来实现这个逻辑： import math</p><p>方法一：for循环 def is_prime(n):</p><h1 id="小于2的数不是质数" tabindex="-1">小于2的数不是质数 <a class="header-anchor" href="#小于2的数不是质数" aria-label="Permalink to &quot;小于2的数不是质数&quot;">​</a></h1><p>if n &lt; 2: return False</p><h1 id="检查2到n的平方根之间的数是否能整除n" tabindex="-1">检查2到n的平方根之间的数是否能整除n <a class="header-anchor" href="#检查2到n的平方根之间的数是否能整除n" aria-label="Permalink to &quot;检查2到n的平方根之间的数是否能整除n&quot;">​</a></h1><p>for i in range(2, int(math.sqrt(n)) + 1): if n % i == 0: return False return True</p><h1 id="测试函数" tabindex="-1">测试函数 <a class="header-anchor" href="#测试函数" aria-label="Permalink to &quot;测试函数&quot;">​</a></h1><p>print(is_prime(1)) # False print(is_prime(2)) # True print(is_prime(29)) # True print(is_prime(30)) # False</p><p>方法二：while循环 def is_prime(num): if num == 1: return False i = 2 while i * i &lt;= num: if num % i == 0: return False i += 1 return True</p><p>这段代码首先检查数是否小于2（质数定义中的条件），然后通过循环从2检查到该数的平方根，检查是否存在能够整除该数的因子。如果找到这样的因子，函数返回<code>False</code>，表明这个数不是质数；如果没有找到，函数返回<code>True</code>，表明这个数是质数。</p><p>这种方法在数学上是有效的，并且对于绝大多数的质数检查来说都是高效的。对于非常大的数，可能需要更高效的算法来进行质数检查。</p></div>',1)])])}const h=t(n,[["render",o]]);export{_ as __pageData,h as default};
